	mappingInfo := &shadowV1.DynamicFieldMappingInfo{
		Id:          item.ID,
		Channel:     item.Channel,
		MappingType: item.MappingType,
	}
	mappingInfo.Data = make([]*shadowV1.DynamicFieldMappingItem, 0)
	if len(item.Data) > 0 {
		var mappingData []*shadowV1.DynamicFieldMappingItem
