<script setup lang="ts">
/**
 * 通用表格组件
 *
 * 使用说明：
 * 1. 组件集成了搜索、表格、分页功能
 * 2. 支持自定义搜索条件和表格列
 * 3. 提供多个插槽用于自定义内容
 * 4. 支持表格数据的刷新和重置
 * 5. 支持表格多选功能
 *
 * 示例：
 * ```vue
 * <CommonTable
 *   ref="tableRef"
 *   :fetch-data="getList"
 *   :search-form="searchForm"
 *   :show-search="true"
 *   @selection-change="handleSelectionChange"
 * >
 *   <!-- 搜索条件 -->
 *   <template #search-items>
 *     <el-form-item label="名称">
 *       <el-input v-model="searchForm.name" />
 *     </el-form-item>
 *   </template>
 *
 *   <!-- 表格选择列 -->
 *   <el-table-column type="selection" width="55" />
 *
 *   <!-- 表格列 -->
 *   <el-table-column prop="name" label="名称" />
 * </CommonTable>
 * ```
 */

import { ref, onMounted, useSlots } from 'vue'
import type { FormInstance, TableProps } from 'element-plus'
import { debug } from 'console'

/**
 * 组件属性定义
 * @interface Props
 * @property {Function} fetchData - 获取表格数据的方法，需要返回 { list: any[], total: number }
 * @property {Object} searchForm - 搜索表单数据对象
 * @property {number} [pageSize=20] - 默认每页显示条数
 * @property {boolean} [showSearch=true] - 是否显示搜索区域
 */
interface Props extends Omit<TableProps<any>, 'data'> {
  fetchData: (params: any) => Promise<{ list: any[]; total: number }>
  searchForm?: Record<string, any>
  defaultSearchForm?: Record<string, any>
  resetSearchForm?: () => void
  pageSize?: number
  showSearch?: boolean
}

const props = withDefaults(defineProps<Props>(), {
  showSearch: true,
  searchForm: () => ({}),
  defaultSearchForm: () => ({}),
  resetSearchForm: () => { },
  pageSize: 20,
  rowKey: 'id',
})

const slots = useSlots()

// 定义事件
const emit = defineEmits(['selection-change'])

/**
 * 表单相关
 */
const searchFormRef = ref<FormInstance>()
const defaultSearchForm = structuredClone(
  props.defaultSearchForm || props.searchForm,
)

/**
 * 表格相关状态
 */
const loading = ref(false)
const tableData = ref<any[]>([])
const currentPage = ref(1)
const pageSize = ref(props.pageSize)
const total = ref(0)
const selectedRows = ref<any[]>([])

/**
 * 对外暴露的方法
 * refresh: 刷新表格数据
 * reset: 重置搜索条件和表格数据
 * getSelectedRows: 获取选中的行数据
 * clearSelection: 清空表格选择
 */
defineExpose({
  refresh,
  reset: handleReset,
  getSelectedRows: () => selectedRows.value,
  clearSelection: () => {
    selectedRows.value = []
  },
})

/**
 * 加载表格数据
 * 合并分页参数和搜索条件
 */
async function loadData() {
  loading.value = true
  try {
    const params = {
      ...props.searchForm,
      page: currentPage.value,
      pageSize: pageSize.value,
    }
    const { list, total: totalCount } = await props.fetchData(params)
    tableData.value = list
    total.value = totalCount
  } catch (error) {
    console.error('加载数据失败：', error)
  } finally {
    loading.value = false
  }
}

/**
 * 刷新表格数据
 * 保持当前页码和每页条数
 */
function refresh() {
  loadData()
}

/**
 * 处理搜索操作
 * 重置页码到第一页
 */
function handleSearch() {
  currentPage.value = 1
  loadData()
}

/**
 * 重置搜索条件和表格数据
 * 恢复默认搜索条件
 */
function handleReset() {
  if (searchFormRef.value) {
    searchFormRef.value.resetFields()
    // 深层重置搜索表单，确保嵌套对象也被重置
    Object.keys(defaultSearchForm).forEach((key) => {
      if (
        typeof defaultSearchForm[key] === 'object' &&
        defaultSearchForm[key] !== null
      ) {
        props.searchForm[key] = JSON.parse(
          JSON.stringify(defaultSearchForm[key]),
        )
      } else {
        props.searchForm[key] = defaultSearchForm[key]
      }
    })
  }
  currentPage.value = 1
  loadData()
  props.resetSearchForm()
}

/**
 * 处理每页显示条数变化
 */
function handleSizeChange(val: number) {
  pageSize.value = val
  loadData()
}

/**
 * 处理页码变化
 */
function handleCurrentChange(val: number) {
  currentPage.value = val
  loadData()
}

/**
 * 处理表格多选
 * 并触发selection-change事件
 */
function handleSelectionChange(val: any[]) {
  selectedRows.value = val
  emit('selection-change', val)
}

// 组件挂载时加载数据
onMounted(() => {
  loadData()
})
</script>

